use std::{fs, thread, time::Duration};
fn main() {
    if cfg!(windows) && std::env::var_os("CONDUCTOR_NATIVE_CURSOR_ENV_TEST").is_some() {
        assert_eq!(std::env::var("MSYSTEM").unwrap(), "MINGW64");
        assert_eq!(std::env::var("SHELL").unwrap(), "/usr/bin/bash");
        assert_eq!(std::env::var("CONDUCTOR_ENV_SENTINEL").unwrap(), "preserved");
    }
    let mode = std::env::args().nth(1).unwrap_or_default();
    if mode == "platform" {
        let name = if cfg!(windows) { "ProgramFiles" } else { "HOME" };
        assert_eq!(std::env::var(name).unwrap(), std::env::args().nth(2).unwrap());
        assert!(std::env::var_os("OPENAI_API_KEY").is_none());
    }
    if mode == "hang" { loop { thread::sleep(Duration::from_millis(50)); } }
    if mode == "progress_demo" {
        println!("Independent fixture verifier started");
        let release = std::env::var_os("CONDUCTOR_TEST_VERIFY_RELEASE").expect("fixture release path");
        while !std::path::Path::new(&release).exists() { thread::sleep(Duration::from_millis(50)); }
    }
    if mode == "mutate" { fs::write("src/result.txt", "verifier changed the source").unwrap(); return; }
    if mode == "extra" { fs::write("outside.txt", "unexpected").unwrap(); return; }
    let expected = fs::read_to_string("verification.txt").unwrap();
    let actual = fs::read_to_string("src/result.txt").unwrap();
    if mode != "quiet" { println!("checking generated bytes against protected independent contract"); }
    if actual != expected { eprintln!("result was {actual:?}; expected {expected:?}"); std::process::exit(7); }
}
